?><section class="admin-shell"><aside class="admin-sidebar"><a href="<?= e(url('admin/dashboard.php')) ?>">← Dashboard</a></aside><div class="admin-content"><p class="eyebrow">Correspondence</p><h1>Enquiries</h1><?php include __DIR__.'/../includes/alerts.php';?><div class="table-wrap"><table><thead><tr><th>Received</th><th>Contact</th><th>Subject and message</th><th>Status</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= e(date('d M Y',strtotime($item['created_at']))) ?></td><td><?= e($item['name']) ?><br><?= e($item['email']) ?><br><?= e($item['phone']) ?></td><td><strong><?= e($item['subject']) ?></strong><br><?= e($item['message']) ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><select name="status"><option <?= $item['status']==='new'?'selected':'' ?>>new</option><option <?= $item['status']==='read'?'selected':'' ?>>read</option><option <?= $item['status']==='resolved'?'selected':'' ?>>resolved</option></select><button class="button button-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php include __DIR__.'/../includes/footer.php';?>